// docs:build refuses to start without the browser runtime, so the site can never ship a 运行 button
// whose runtime is missing. The runtime is generated by `npm run docs:runtime` and stays out of git.
import { existsSync, readFileSync } from 'node:fs'
import { dirname, join, relative } from 'node:path'
import { fileURLToPath } from 'node:url'

const repositoryRoot = join(dirname(fileURLToPath(import.meta.url)), '..')
const runtime = join(repositoryRoot, 'docs', 'public', 'runtime')
const problems = []

const required = ['_framework/dotnet.js', 'refs/manifest.json']
for (const path of required) if (!existsSync(join(runtime, path))) problems.push(`missing ${path}`)

if (problems.length === 0) {
  try {
    const manifest = JSON.parse(readFileSync(join(runtime, 'refs', 'manifest.json'), 'utf8'))
    if (manifest.version !== 1 || !Array.isArray(manifest.references) || !Array.isArray(manifest.assemblies)) {
      problems.push('refs/manifest.json must carry version 1, references[] and assemblies[]')
    } else {
      if (!manifest.assemblies.includes('DataStructureAndAlgorithm.dll')) problems.push('refs/manifest.json does not list DataStructureAndAlgorithm.dll')
      for (const name of manifest.references) if (!existsSync(join(runtime, 'refs', name))) problems.push(`missing refs/${name}`)
      for (const name of manifest.assemblies) if (!manifest.references.includes(name)) problems.push(`refs/manifest.json: assembly ${name} is not also a reference`)
    }
  } catch (error) {
    problems.push(`refs/manifest.json is unreadable: ${error instanceof Error ? error.message : String(error)}`)
  }
}

if (problems.length) {
  console.error(`浏览器运行时不完整（${relative(repositoryRoot, runtime)}）：`)
  for (const problem of problems) console.error(`- ${problem}`)
  console.error('先运行 npm run docs:runtime（需要 .NET 10 SDK 以及 wasm-tools、wasm-experimental 两个工作负载），再运行 docs:build。')
  process.exit(1)
}
console.log('Browser runtime is present; the build can go on.')
